/* Firebird Designer Online — interface sem dependências externas.
   Este editor modela um banco em memória/localStorage. A API gera .FDB REAL.
*/
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHtml = x => String(x ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => (globalThis.crypto?.randomUUID?.() || 'id_'+Date.now()+'_'+Math.random().toString(36).slice(2));
const clone = o => JSON.parse(JSON.stringify(o));
const cleanIdent = s => String(s||'').trim().toUpperCase();
const validIdent = s => /^[A-Z][A-Z0-9_]{0,30}$/.test(cleanIdent(s));
const fieldTypes = ['SMALLINT','INTEGER','BIGINT','VARCHAR','CHAR','DATE','TIME','TIMESTAMP','NUMERIC','DECIMAL','FLOAT','DOUBLE PRECISION','BOOLEAN','BLOB SUB_TYPE TEXT'];
const TYPES = {int:['SMALLINT','INTEGER','BIGINT'], decimal:['NUMERIC','DECIMAL','FLOAT','DOUBLE PRECISION'], text:['VARCHAR','CHAR','BLOB SUB_TYPE TEXT']};
const storageKey = 'firebird-designer-v2';
const newField=(name,type='VARCHAR',opts={})=>({id:uid(),name,type,length:80,precision:12,scale:2,required:false,primary:false,identity:false,defaultValue:'',...opts});
const newTable=(name,fields=[newField('ID','INTEGER',{primary:true,required:true,identity:true}),newField('NOME','VARCHAR',{length:120})])=>({id:uid(),name,description:'',fields,records:[],indexes:[],foreignKeys:[]});
function sampleProject(){
 const clientes=newTable('CLIENTES',[newField('ID','INTEGER',{primary:true,required:true,identity:true}),newField('NOME','VARCHAR',{length:120,required:true}),newField('EMAIL','VARCHAR',{length:150}),newField('CIDADE','VARCHAR',{length:80}),newField('ATIVO','BOOLEAN',{defaultValue:'TRUE'})]);
 clientes.description='Cadastro de clientes da empresa';
 clientes.records=[{ID:1,NOME:'Maria Silva',EMAIL:'maria@exemplo.com',CIDADE:'Pouso Alegre',ATIVO:true},{ID:2,NOME:'João Souza',EMAIL:'joao@exemplo.com',CIDADE:'Belo Horizonte',ATIVO:true},{ID:3,NOME:'Ana Oliveira',EMAIL:'ana@exemplo.com',CIDADE:'São Paulo',ATIVO:false}];
 const produtos=newTable('PRODUTOS',[newField('ID','INTEGER',{primary:true,required:true,identity:true}),newField('DESCRICAO','VARCHAR',{length:150,required:true}),newField('PRECO','DECIMAL',{precision:12,scale:2,required:true}),newField('ESTOQUE','INTEGER',{defaultValue:'0'})]);
 produtos.description='Catálogo de produtos';
 produtos.records=[{ID:1,DESCRICAO:'Teclado',PRECO:'89.90',ESTOQUE:15},{ID:2,DESCRICAO:'Mouse',PRECO:'49.90',ESTOQUE:30}];
 const vendas=newTable('VENDAS',[newField('ID','INTEGER',{primary:true,required:true,identity:true}),newField('CLIENTE_ID','INTEGER',{required:true}),newField('PRODUTO_ID','INTEGER',{required:true}),newField('QUANTIDADE','INTEGER',{required:true,defaultValue:'1'}),newField('DATA_VENDA','DATE',{defaultValue:'CURRENT_DATE'})]);
 vendas.description='Pedidos e relacionamento com clientes e produtos';
 vendas.foreignKeys=[{id:uid(),name:'FK_VENDA_CLIENTE',field:'CLIENTE_ID',refTable:'CLIENTES',refField:'ID',onDelete:'NO ACTION'},{id:uid(),name:'FK_VENDA_PRODUTO',field:'PRODUTO_ID',refTable:'PRODUTOS',refField:'ID',onDelete:'NO ACTION'}];
 vendas.records=[{ID:1,CLIENTE_ID:1,PRODUTO_ID:2,QUANTIDADE:2,DATA_VENDA:'2026-10-29'}];
 return {version:2,name:'COMERCIAL',charset:'UTF8',tables:[clientes,produtos,vendas]};
}
let project;
try {project=JSON.parse(localStorage.getItem(storageKey)); if(!project||!Array.isArray(project.tables))throw 0;}catch(e){project=sampleProject()}
let currentId=project.tables[0]?.id||null;
let activeView='structure', selectedFieldId=null, editorSql='SELECT * FROM CLIENTES;', queryResults=null, dataFilter='', fdbAvailable=false;
let undoStack=[],redoStack=[],saveTimer=null;
const current=()=>project.tables.find(t=>t.id===currentId)||project.tables[0]||null;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(project));$('#saveIndicator').title='Salvo no navegador';}catch(e){toast('Armazenamento do navegador cheio. Exporte um JSON para não perder seu trabalho.','error');}}
function mutate(callback,message){undoStack.push(clone(project));if(undoStack.length>35)undoStack.shift();redoStack=[];callback();save();render();if(message)status(message)}
function status(msg){$('#statusText').textContent=msg;}
function toast(msg,type='success'){
 const div=document.createElement('div');div.className='toast '+type;div.textContent=(type==='error'?'⚠ ':'✓ ')+msg;$('#toastRoot').append(div);setTimeout(()=>div.remove(),4500);
}
function undo(){if(!undoStack.length)return;redoStack.push(clone(project));project=undoStack.pop();ensureCurrent();save();render();status('Alteração desfeita')}
function redo(){if(!redoStack.length)return;undoStack.push(clone(project));project=redoStack.pop();ensureCurrent();save();render();status('Alteração refeita')}
function ensureCurrent(){if(!project.tables.some(t=>t.id===currentId))currentId=project.tables[0]?.id||null}
function render(){
 ensureCurrent();const t=current();
 $('#sideDbName').textContent=project.name;$('#renameProject').innerHTML=escapeHtml(project.name)+' <span>⌄</span>';
 $('#tableCount').textContent=project.tables.length;$('#statusTables').textContent=project.tables.length+' tabela'+(project.tables.length!==1?'s':'');
 $('#tableTree').innerHTML=project.tables.map(tab=>`<div class="tree-item ${tab.id===currentId?'selected':''}" data-table="${tab.id}" title="${escapeHtml(tab.description||tab.name)}"><span class="tree-ico">▦</span><span class="tree-text">${escapeHtml(tab.name)}</span><small>${tab.fields.length}</small></div>`).join('')+(!project.tables.length?'<div class="empty"><p>Nenhuma tabela criada</p></div>':'');
 $('#tabName').textContent=t?.name||'PROJETO';$('#tableTitle').textContent=t?.name||'Nenhuma tabela';$('#tableSubtitle').textContent=t?.description||'Crie tabelas e edite a estrutura do banco';
 $$('.nav-item').forEach(btn=>btn.classList.toggle('active',btn.dataset.view===activeView));
 $('#duplicateTable').disabled=!t;$('#editTableName').disabled=!t;$('#deleteTable').disabled=!t;
 if(!t){$('#mainContent').innerHTML=`<div class="empty"><div class="empty-icon">▦</div><strong>Seu banco está vazio</strong><p>Crie uma tabela para adicionar campos, registros e relacionamentos.</p><button class="btn primary" id="emptyCreate">＋ Criar primeira tabela</button></div>`;}
 else if(activeView==='structure')renderStructure(t);
 else if(activeView==='data')renderData(t);
 else if(activeView==='relations')renderRelations(t);
 else if(activeView==='sql')renderSql(t);
 else if(activeView==='diagram')renderDiagram(t);
 renderInspector(t);
}
function renderCards(t){return `<div class="meta-cards"><div class="meta-card"><div><small>Campos</small><strong>${t.fields.length}</strong></div><div class="meta-icon">▥</div></div><div class="meta-card"><div><small>Registros</small><strong>${t.records.length}</strong></div><div class="meta-icon">▦</div></div><div class="meta-card"><div><small>Relacionamentos</small><strong>${t.foreignKeys.length}</strong></div><div class="meta-icon">⌁</div></div><div class="meta-card"><div><small>Índices</small><strong>${t.indexes.length}</strong></div><div class="meta-icon">◇</div></div></div>`}
function opt(items, val){return items.map(s=>`<option value="${escapeHtml(s)}" ${s===val?'selected':''}>${escapeHtml(s)}</option>`).join('')}
function renderStructure(t){
 $('#mainContent').innerHTML=renderCards(t)+`<div class="section-title"><div><h2>Campos da tabela</h2><p>Configure os tipos de dados, chaves primárias e valores padrão.</p></div><button class="btn primary" id="addField">＋ Adicionar campo</button></div>
 <div class="panel table-wrap"><table class="data-table fields-table"><thead><tr><th>#</th><th style="min-width:140px">NOME DO CAMPO</th><th style="min-width:168px">TIPO</th><th style="min-width:77px">TAMANHO</th><th>PK</th><th>OBRIG.</th><th>IDENTITY</th><th style="min-width:110px">DEFAULT</th><th></th></tr></thead><tbody>${t.fields.map((f,i)=>`<tr data-field="${f.id}"><td class="row-num">${i+1}</td><td><input class="field-edit" data-key="name" aria-label="Nome" value="${escapeHtml(f.name)}" spellcheck="false"></td><td><select class="field-edit" data-key="type">${opt(fieldTypes,f.type)}</select></td><td><input class="field-edit" data-key="length" type="number" min="1" max="8191" value="${['VARCHAR','CHAR'].includes(f.type)?f.length:(['DECIMAL','NUMERIC'].includes(f.type)?f.precision:'')}" ${!['VARCHAR','CHAR','DECIMAL','NUMERIC'].includes(f.type)?'disabled':''} title="Para NUMERIC/DECIMAL: precisão"></td><td><input class="field-edit" data-key="primary" type="checkbox" ${f.primary?'checked':''} aria-label="Chave primária"></td><td><input class="field-edit" data-key="required" type="checkbox" ${f.required||f.primary?'checked':''} ${f.primary?'disabled':''} aria-label="Obrigatório"></td><td><input class="field-edit" data-key="identity" type="checkbox" ${f.identity?'checked':''} ${!TYPES.int.includes(f.type)?'disabled':''} aria-label="Autoincremento"></td><td><input class="field-edit" data-key="defaultValue" value="${escapeHtml(f.defaultValue||'')}" placeholder="NULL" spellcheck="false"></td><td><button class="text-button" data-act="selectField" title="Propriedades">⚙</button><button class="text-button danger" data-act="deleteField" title="Excluir">✕</button></td></tr>`).join('')}</tbody></table><div class="small-note">🔑 PK = chave primária · IDENTITY = numeração automática · alterações são salvas no navegador.</div></div>
 <div class="section-title"><div><h2>Índices</h2><p>Melhore a busca de registros definindo índices simples ou compostos.</p></div><button class="btn subtle" id="addIndex">＋ Novo índice</button></div>
 <div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>NOME</th><th>CAMPOS</th><th>TIPO</th><th></th></tr></thead><tbody>${t.indexes.map(ix=>`<tr><td><span class="tag blue">◇</span> &nbsp; ${escapeHtml(ix.name)}</td><td>${escapeHtml(ix.fields.join(', '))}</td><td>${ix.unique?'Único':'Normal'}</td><td style="text-align:right"><button class="text-button danger" data-remove-index="${ix.id}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="4" class="muted">Nenhum índice secundário. Chaves primárias geram índice automaticamente.</td></tr>'}</tbody></table></div></div>`;
}
function renderData(t){
 const q=dataFilter.trim().toLowerCase();let rows=t.records.map((r,i)=>({r,i})).filter(({r})=>!q||Object.values(r).some(v=>String(v??'').toLowerCase().includes(q)));
 $('#mainContent').innerHTML=`<div class="section-title"><div><h2>Registros de ${escapeHtml(t.name)}</h2><p>Adicione ou edite dados. Os registros entram no arquivo FDB exportado.</p></div><div class="section-actions"><button class="btn subtle" id="importCSV">↥ CSV</button><button class="btn subtle" id="downloadCSV">⇩ CSV</button><button class="btn primary" id="newRecord">＋ Novo registro</button></div></div><div class="toolbar"><div class="search"><span>⌕</span><input id="dataSearch" placeholder="Filtrar registros..." value="${escapeHtml(dataFilter)}"></div><span class="muted" id="filterCount">${rows.length} de ${t.records.length} registros</span></div>
 <div class="panel table-wrap"><table class="data-table"><thead><tr><th>#</th>${t.fields.map(f=>`<th>${f.primary?'🔑 ':''}${escapeHtml(f.name)} <span class="muted">${escapeHtml(f.type)}</span></th>`).join('')}<th>AÇÕES</th></tr></thead><tbody id="recordRows">${rows.slice(0,100).map(({r,i})=>`<tr><td class="row-num">${i+1}</td>${t.fields.map(f=>`<td class="grid-value ${f.primary?'grid-pk':''}">${r[f.name]===null||r[f.name]===undefined||r[f.name]===''?'<span class="grid-null">NULL</span>':escapeHtml(typeof r[f.name]==='boolean'?(r[f.name]?'TRUE':'FALSE'):r[f.name])}</td>`).join('')}<td><button class="text-button" data-edit-record="${i}">Editar</button><button class="text-button danger" data-delete-record="${i}">Excluir</button></td></tr>`).join('')||`<tr><td colspan="${t.fields.length+2}" class="muted">Nenhum registro encontrado.</td></tr>`}</tbody></table>${rows.length>100?'<div class="small-note">Exibindo 100 registros. Use o filtro para localizar os demais.</div>':''}</div>`;
}
function renderRelations(t){
 $('#mainContent').innerHTML=renderCards(t)+`<div class="section-title"><div><h2>Chaves estrangeiras (FK)</h2><p>Relacione campos desta tabela a outras tabelas do projeto.</p></div><button class="btn primary" id="addRelation">＋ Novo relacionamento</button></div><div class="panel table-wrap"><table class="data-table"><thead><tr><th>RESTRIÇÃO</th><th>CAMPO LOCAL</th><th>REFERÊNCIA</th><th>ON DELETE</th><th></th></tr></thead><tbody>${t.foreignKeys.map(fk=>`<tr><td><span class="tag purple">FK</span> &nbsp;${escapeHtml(fk.name)}</td><td>${escapeHtml(fk.field)}</td><td>${escapeHtml(fk.refTable)}.${escapeHtml(fk.refField)}</td><td>${escapeHtml(fk.onDelete)}</td><td style="text-align:right"><button class="text-button danger" data-remove-rel="${fk.id}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted">Nenhum relacionamento nesta tabela.</td></tr>'}</tbody></table></div><div class="tip"><b>Dica:</b> uma chave estrangeira deve apontar para uma chave primária ou campo único na tabela de destino. Ao exportar, as referências são criadas depois das tabelas e dos registros.</div>`;
}
function sqlID(s){return '"'+s.toUpperCase()+'"'}
function sqlFieldType(f){let ty=f.type;if(['VARCHAR','CHAR'].includes(ty))ty+=`(${f.length||80})`;if(['NUMERIC','DECIMAL'].includes(ty))ty+=`(${f.precision||12},${f.scale??2})`;return ty}
function sqlDefault(s){if(s===null||s===undefined||String(s).trim()==='')return '';s=String(s).trim();if(/^(CURRENT_DATE|CURRENT_TIME|CURRENT_TIMESTAMP|NULL|TRUE|FALSE|-?\d+(\.\d+)?)$/i.test(s))return ' DEFAULT '+s;return ` DEFAULT '${s.replace(/'/g,"''")}'`}
function literal(v,f){if(v===null||v===undefined||v==='')return 'NULL';if(TYPES.int.includes(f.type)||TYPES.decimal.includes(f.type))return String(v);if(f.type==='BOOLEAN')return v===true||v===1||v==='1'||String(v).toLowerCase()==='true'?'TRUE':'FALSE';return "'"+String(v).replace(/'/g,"''")+"'"}
function sqlForProject(includeRows=true){
 let out=['-- Firebird Designer Online | compatível com Firebird 3.0','-- SQL Dialect 3 | charset '+project.charset,''];
 for(const t of project.tables){let lines=t.fields.map(f=>`    ${sqlID(f.name)} ${sqlFieldType(f)}${f.identity?' GENERATED BY DEFAULT AS IDENTITY':''}${f.identity?'':sqlDefault(f.defaultValue)}${f.required||f.primary?' NOT NULL':''}`);const pk=t.fields.filter(f=>f.primary).map(f=>sqlID(f.name));if(pk.length)lines.push(`    CONSTRAINT ${sqlID('PK_'+t.name.slice(0,28))} PRIMARY KEY (${pk.join(', ')})`);out.push(`CREATE TABLE ${sqlID(t.name)} (\n${lines.join(',\n')}\n);\n`)}
 if(includeRows)for(const t of project.tables){if(t.records.length)out.push('-- Registros de '+t.name);for(const r of t.records){const fs=t.fields.filter(f=>r[f.name]!==null&&r[f.name]!==undefined&&r[f.name]!=='');out.push(fs.length?`INSERT INTO ${sqlID(t.name)} (${fs.map(f=>sqlID(f.name)).join(', ')}) VALUES (${fs.map(f=>literal(r[f.name],f)).join(', ')});`:`INSERT INTO ${sqlID(t.name)} DEFAULT VALUES;`)}if(t.records.length)out.push('')}
 out.push('COMMIT;','');for(const t of project.tables){for(const f of t.fields){if(f.identity){const vals=t.records.map(r=>Number(r[f.name])).filter(Number.isFinite);if(vals.length)out.push(`ALTER TABLE ${sqlID(t.name)} ALTER ${sqlID(f.name)} RESTART WITH ${Math.max(1,...vals.map(v=>v+1))};`)}}}for(const t of project.tables){for(const ix of t.indexes)out.push(`CREATE ${ix.unique?'UNIQUE ':''}INDEX ${sqlID(ix.name)} ON ${sqlID(t.name)} (${ix.fields.map(sqlID).join(', ')});`);for(const fk of t.foreignKeys)out.push(`ALTER TABLE ${sqlID(t.name)} ADD CONSTRAINT ${sqlID(fk.name)} FOREIGN KEY (${sqlID(fk.field)}) REFERENCES ${sqlID(fk.refTable)} (${sqlID(fk.refField)}) ON DELETE ${fk.onDelete};`)}out.push('','COMMIT;');return out.join('\n')+'\n'
}
function sqlColor(code){return escapeHtml(code).replace(/(--[^\n]*)|('[^']*(?:''[^']*)*')|(&quot;[^&]*?&quot;)|\b(CREATE|TABLE|ALTER|ADD|CONSTRAINT|PRIMARY|KEY|FOREIGN|REFERENCES|INSERT|INTO|VALUES|DEFAULT|NOT|NULL|UNIQUE|INDEX|ON|DELETE|CASCADE|SET|SELECT|FROM|WHERE|ORDER|BY|ASC|DESC|COUNT|AS|COMMIT|GENERATED|ALWAYS|IDENTITY|TRUE|FALSE|CURRENT_DATE|CURRENT_TIMESTAMP|CURRENT_TIME)\b|\b(VARCHAR|INTEGER|BIGINT|SMALLINT|NUMERIC|DECIMAL|FLOAT|DOUBLE|PRECISION|BOOLEAN|DATE|TIME|TIMESTAMP|CHAR|BLOB|SUB_TYPE|TEXT)\b|\b(\d+(?:\.\d+)?)\b/gi,(m,comment,str,quoted,keyword,type,num)=>comment?`<span class="sql-comment">${m}</span>`:str?`<span class="sql-string">${m}</span>`:quoted?`<span class="sql-quote">${m}</span>`:keyword?`<span class="sql-kw">${m}</span>`:type?`<span class="sql-type">${m}</span>`:num?`<span class="sql-num">${m}</span>`:m)}
function renderSql(t){
 const sql=sqlForProject(true);
 $('#mainContent').innerHTML=`<div class="section-title"><div><h2>Script SQL do banco</h2><p>Comandos gerados automaticamente para todas as tabelas do projeto.</p></div><div class="section-actions"><button class="btn subtle" id="copySQL">▣ Copiar</button><button class="btn primary" id="downloadSQL">⇩ Baixar .SQL</button></div></div><div class="code-area"><div class="code-toolbar"><span>▦ &nbsp; ${escapeHtml(project.name)}.sql &nbsp; <span class="muted">· Firebird 3.0</span></span><span>${sql.split('\n').length} linhas</span></div><pre class="code-code">${sqlColor(sql)}</pre></div>
 <div class="section-title" style="margin-top:27px"><div><h2>Console de consultas</h2><p>Execute SELECT e COUNT simples nos registros do projeto, sem servidor.</p></div><button class="btn subtle" id="runQuery">▶ Executar consulta</button></div><div class="code-area"><div class="code-toolbar">⌘ &nbsp; Consulta local <span class="tag">SELECT / COUNT</span></div><textarea spellcheck="false" id="queryEditor" class="sql-editor" aria-label="Editor SQL">${escapeHtml(editorSql)}</textarea></div><div class="panel" id="queryResult" style="margin-top:14px">${queryResults?queryResults:'<div class="small-note">Escreva uma consulta simples, como SELECT * FROM CLIENTES; e clique em Executar consulta.</div>'}</div>
 <div class="tip"><b>Console local:</b> executa apenas SELECT, COUNT, WHERE simples e ORDER BY sobre os registros que você editou no navegador. Para executar SQL completo no Firebird, exporte o .FDB e abra-o no IBExpert.</div>`;
}
function renderDiagram(){
 $('#mainContent').innerHTML=`<div class="section-title"><div><h2>Diagrama de entidades</h2><p>Visão geral das tabelas e colunas do seu projeto.</p></div><button class="btn subtle" id="diagramPrint">⎙ Imprimir</button></div><div class="diagram"><div class="diagram-boxes">${project.tables.map(t=>`<div class="diagram-table" title="Abrir ${escapeHtml(t.name)}" data-diagram-table="${t.id}" style="cursor:pointer"><div class="diagram-name">▦ &nbsp;${escapeHtml(t.name)}</div>${t.fields.map(f=>`<div class="diagram-col"><span>${f.primary?'🔑 ':''}${t.foreignKeys.some(k=>k.field===f.name)?'⌁ ':''}${escapeHtml(f.name)}</span><span class="type">${escapeHtml(f.type)}</span></div>`).join('')}</div>`).join('')}</div><div class="diagram-rel">${project.tables.flatMap(t=>t.foreignKeys.map(fk=>`${escapeHtml(t.name)}.${escapeHtml(fk.field)} &nbsp; ⟶ &nbsp; ${escapeHtml(fk.refTable)}.${escapeHtml(fk.refField)}`)).join('<hr class="secondary-line">')||'Crie relacionamentos na aba Relacionamentos para vê-los aqui.'}</div></div>`;
}
function renderInspector(t){
 if(!t){$('#inspectorContent').innerHTML='<div class="inspect-section muted">Crie uma tabela para visualizar as propriedades.</div>';return}
 const f=t.fields.find(f=>f.id===selectedFieldId);
 $('#inspectorContent').innerHTML=`<div class="inspect-section"><div class="inspect-title">${f?'▤ Propriedades do campo':'▦ Propriedades da tabela'}</div>${f?`<span class="inspect-chip">${escapeHtml(f.name)}</span><div class="inspect-field"><label>Nome</label><input data-inspect="field-name" value="${escapeHtml(f.name)}"></div><div class="inspect-field"><label>Tipo</label><select data-inspect="field-type">${opt(fieldTypes,f.type)}</select></div>${['DECIMAL','NUMERIC'].includes(f.type)?`<div class="inspect-field"><label>Precisão (1–18)</label><input type="number" min="1" max="18" data-inspect="precision" value="${f.precision}"></div><div class="inspect-field"><label>Casas decimais</label><input type="number" min="0" max="18" data-inspect="scale" value="${f.scale}"></div>`:''}<div class="inspect-field"><label>Padrão</label><input data-inspect="defaultValue" value="${escapeHtml(f.defaultValue||'')}"></div><button class="btn subtle" id="clearFieldSelection">Voltar para tabela</button>`:`<div class="inspect-field"><label>Nome do banco</label><input data-inspect="project-name" value="${escapeHtml(project.name)}"></div><div class="inspect-field"><label>Nome da tabela</label><input data-inspect="table-name" value="${escapeHtml(t.name)}"></div><div class="inspect-field"><label>Descrição</label><textarea data-inspect="table-desc" rows="3">${escapeHtml(t.description)}</textarea></div><div class="inspect-field"><label>Charset do banco</label><select data-inspect="project-charset">${opt(['UTF8','WIN1252','ISO8859_1','NONE'],project.charset)}</select></div><hr class="inspect-divider"><div class="inspect-field"><label>Dialect</label><span class="tag orange">SQL Dialect 3</span></div>`}<hr class="inspect-divider"><div class="inspect-title">Sobre a exportação</div><div class="inspect-info">O projeto fica no navegador. Você pode baixar JSON, SQL, CSV ou um banco .FDB gerado com Firebird Embedded 3 no servidor.</div><div style="margin-top:13px"><button class="btn subtle" id="inspectExport">⇩ Exportar projeto</button></div></div>`;
}
function openModal(title,body,footer='',wide=false){
 $('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><div class="modal-head"><h2>${escapeHtml(title)}</h2><button class="modal-x" data-close title="Fechar">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer||'<button class="btn subtle" data-close>Fechar</button>'}</div></div></div>`;
 $$('.modal-backdrop').forEach(el=>el.addEventListener('mousedown',e=>{if(e.target===el)closeModal()}));
 const first=$('.modal input:not([type=checkbox]),.modal select');if(first)first.focus();
}
function closeModal(){$('#modalRoot').innerHTML=''}
function askName(title,label,initial,onSave){openModal(title,`<form id="nameForm"><div class="form-grid"><div class="full"><label>${label}</label><input id="modalName" name="name" value="${escapeHtml(initial)}" maxlength="31" autocomplete="off" required spellcheck="false"><div class="footer-hint">Use letras, números e underline. Máximo de 31 caracteres.</div></div></div></form>`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn primary" id="modalSaveName">Salvar</button>`);
 const go=()=>{const name=cleanIdent($('#modalName').value);if(!validIdent(name))return toast('Nome inválido. Ex.: MINHA_TABELA','error');if(onSave(name)!==false)closeModal()};$('#modalSaveName').onclick=go;$('#nameForm').onsubmit=e=>{e.preventDefault();go()};}
function validateTableName(name,exceptId){if(project.tables.some(t=>t.name===name&&t.id!==exceptId)){toast('Já existe uma tabela com esse nome.','error');return false}return true}
function newDatabase(){
 openModal('Criar novo banco Firebird',`<form id="newDatabaseForm"><div class="form-grid"><div class="full"><label>Nome do novo banco</label><input id="newDbName" value="MEU_BANCO" maxlength="31" required spellcheck="false"></div><div class="full"><label>Modelo inicial</label><select id="newDbMode"><option value="empty">Banco vazio (começar do zero)</option><option value="sample">Com tabelas de exemplo</option></select></div></div></form><div class="footer-hint">Seu projeto atual continua disponível se você baixá-lo como .JSON antes. Criar outro banco substitui o projeto local aberto.</div>`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn primary" id="confirmNewDb">Criar banco</button>`);
 const go=()=>{const name=cleanIdent($('#newDbName').value),mode=$('#newDbMode').value;if(!validIdent(name))return toast('Use um nome válido com até 31 caracteres','error');mutate(()=>{project=mode==='sample'?sampleProject():{version:2,name,charset:'UTF8',tables:[]};project.name=name;currentId=project.tables[0]?.id||null;selectedFieldId=null;activeView='structure'},'Novo banco criado: '+name);closeModal();toast('Banco '+name+' criado no editor')};
 $('#confirmNewDb').onclick=go;$('#newDatabaseForm').onsubmit=e=>{e.preventDefault();go()};
}
function createTable(){askName('Nova tabela','Nome da tabela','NOVA_TABELA',name=>{if(!validateTableName(name))return false;mutate(()=>{const t=newTable(name);project.tables.push(t);currentId=t.id;activeView='structure';selectedFieldId=null},'Tabela '+name+' criada');toast('Tabela criada com sucesso')})}
function renameTable(){const t=current();if(!t)return;askName('Renomear tabela','Nome da tabela',t.name,name=>{if(!validateTableName(name,t.id))return false;mutate(()=>{const old=t.name;t.name=name;project.tables.forEach(tab=>tab.foreignKeys.forEach(fk=>{if(fk.refTable===old)fk.refTable=name}))},'Tabela renomeada')})}
function duplicateTable(){const t=current();if(!t)return;askName('Duplicar tabela','Nome da cópia',t.name+'_COPIA',name=>{if(!validateTableName(name))return false;mutate(()=>{let next=clone(t);next.id=uid();next.name=name;next.fields.forEach(f=>f.id=uid());next.indexes=[];next.foreignKeys=[];next.records=[];project.tables.push(next);currentId=next.id;selectedFieldId=null},'Tabela duplicada (sem dados)');toast('Cópia criada sem registros, índices e relações')})}
function deleteTable(){const t=current();if(!t)return;const inbound=project.tables.flatMap(tab=>tab.foreignKeys.filter(k=>k.refTable===t.name).map(k=>tab.name));openModal('Excluir tabela',`<p>Excluir permanentemente <b>${escapeHtml(t.name)}</b>, seus ${t.records.length} registros e ${t.fields.length} campos?</p>${inbound.length?`<p class="error-msg">Relacionamentos de ${escapeHtml(inbound.join(', '))} também serão excluídos.</p>`:''}<div class="tip">Você pode desfazer esta exclusão usando o botão <b>Desfazer</b>.</div>`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn danger-ghost" id="confirmDeleteTable">Excluir tabela</button>`);$('#confirmDeleteTable').onclick=()=>{mutate(()=>{project.tables=project.tables.filter(tab=>tab.id!==t.id);project.tables.forEach(tab=>tab.foreignKeys=tab.foreignKeys.filter(fk=>fk.refTable!==t.name));currentId=project.tables[0]?.id||null;selectedFieldId=null},'Tabela excluída');closeModal()}}
function addField(){const t=current();if(!t)return;let n=1;while(t.fields.some(f=>f.name==='CAMPO_'+n))n++;mutate(()=>{const f=newField('CAMPO_'+n);t.fields.push(f);selectedFieldId=f.id},'Campo adicionado')}
function updateField(id,key,input){const t=current(),f=t?.fields.find(f=>f.id===id);if(!f)return;let value=input.type==='checkbox'?input.checked:input.value;
 if(key==='name'){value=cleanIdent(value);if(!validIdent(value))return toast('Nome de campo inválido','error');if(t.fields.some(other=>other!==f&&other.name===value))return toast('Já existe um campo com esse nome','error')}
 if(key==='type'&&!fieldTypes.includes(value))return;
 if(key==='length'){const max=['VARCHAR','CHAR'].includes(f.type)?8191:18;value=Number(value);if(!Number.isInteger(value)||value<1||value>max)return toast('Tamanho/precisão inválido','error')}
 if(key==='identity'&&value&&!TYPES.int.includes(f.type))return toast('IDENTITY exige tipo inteiro','error');
 mutate(()=>{
  if(key==='name'){const old=f.name;f.name=value;t.records.forEach(r=>{if(Object.hasOwn(r,old)){r[value]=r[old];delete r[old]}});t.indexes.forEach(ix=>ix.fields=ix.fields.map(s=>s===old?value:s));t.foreignKeys.forEach(fk=>{if(fk.field===old)fk.field=value});project.tables.forEach(tab=>tab.foreignKeys.forEach(fk=>{if(fk.refTable===t.name&&fk.refField===old)fk.refField=value}))}
  else if(key==='length'){if(['VARCHAR','CHAR'].includes(f.type))f.length=value;else f.precision=value}
  else {f[key]=value;if(key==='primary'&&value)f.required=true;if(key==='type'&&!TYPES.int.includes(value))f.identity=false}
 },'Campo '+f.name+' alterado');
}
function deleteField(id){const t=current(),f=t?.fields.find(x=>x.id===id);if(!f)return; if(t.fields.length===1)return toast('Uma tabela deve ter pelo menos um campo','error');openModal('Excluir campo',`Excluir o campo <b>${escapeHtml(f.name)}</b> e seus valores nos registros?`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn danger-ghost" id="deleteFieldConfirm">Excluir</button>`);$('#deleteFieldConfirm').onclick=()=>{mutate(()=>{t.fields=t.fields.filter(x=>x.id!==id);t.records.forEach(r=>delete r[f.name]);t.indexes=t.indexes.filter(ix=>!ix.fields.includes(f.name));t.foreignKeys=t.foreignKeys.filter(fk=>fk.field!==f.name);project.tables.forEach(tab=>tab.foreignKeys=tab.foreignKeys.filter(fk=>!(fk.refTable===t.name&&fk.refField===f.name)));selectedFieldId=null},'Campo excluído');closeModal()}}
function addIndex(){const t=current();const name=('IX_'+t.name+'_1').slice(0,31);openModal('Novo índice',`<div class="form-grid"><div class="full"><label>Nome do índice</label><input id="indexName" maxlength="31" value="${escapeHtml(name)}"></div><div class="full"><label>Campos (Ctrl para selecionar múltiplos)</label><select id="indexFields" multiple size="${Math.min(t.fields.length,7)}">${t.fields.map(f=>`<option value="${escapeHtml(f.name)}">${escapeHtml(f.name)}</option>`).join('')}</select></div><div class="full"><label class="switchline"><input type="checkbox" id="indexUnique"> Índice único (UNIQUE)</label></div></div>`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn primary" id="saveIndex">Criar índice</button>`);$('#saveIndex').onclick=()=>{const name=cleanIdent($('#indexName').value);const fields=[...$('#indexFields').selectedOptions].map(o=>o.value);if(!validIdent(name)||!fields.length)return toast('Preencha nome válido e selecione campos.','error');if(project.tables.flatMap(x=>x.indexes).some(x=>x.name===name)||project.tables.flatMap(x=>x.foreignKeys).some(x=>x.name===name))return toast('Já existe índice ou restrição com esse nome','error');mutate(()=>t.indexes.push({id:uid(),name,fields,unique:$('#indexUnique').checked}),'Índice '+name+' criado');closeModal()}}
function addRelation(){const t=current();const others=project.tables.filter(x=>x.fields.length);if(!others.length)return toast('Crie tabelas antes de adicionar relações.','error');openModal('Novo relacionamento',`<div class="form-grid"><div class="full"><label>Nome da chave estrangeira</label><input id="fkName" maxlength="31" value="${escapeHtml(('FK_'+t.name+'_1').slice(0,31))}"></div><div><label>Campo nesta tabela</label><select id="fkField">${opt(t.fields.map(x=>x.name),t.fields[0].name)}</select></div><div><label>Tabela de destino</label><select id="fkTarget">${opt(others.map(x=>x.name),others[0].name)}</select></div><div><label>Campo de destino</label><select id="fkTargetField"></select></div><div><label>Ao excluir registro pai</label><select id="fkDelete">${opt(['NO ACTION','CASCADE','SET NULL'],'NO ACTION')}</select></div></div><div class="footer-hint">O campo de destino deve ser uma chave primária ou ter restrição UNIQUE.</div>`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn primary" id="saveRel">Criar relacionamento</button>`);
 const update=()=>{const dest=project.tables.find(x=>x.name===$('#fkTarget').value);$('#fkTargetField').innerHTML=dest.fields.map(f=>`<option value="${escapeHtml(f.name)}" ${f.primary?'selected':''}>${escapeHtml(f.name)}${f.primary?' (PK)':''}</option>`).join('')};$('#fkTarget').onchange=update;update();$('#saveRel').onclick=()=>{const name=cleanIdent($('#fkName').value),field=$('#fkField').value,refTable=$('#fkTarget').value,refField=$('#fkTargetField').value,onDelete=$('#fkDelete').value;const dest=project.tables.find(x=>x.name===refTable),df=dest?.fields.find(f=>f.name===refField),sf=t.fields.find(f=>f.name===field);if(!validIdent(name))return toast('Nome inválido','error');if(!df||!(df.primary||dest.indexes.some(ix=>ix.unique&&ix.fields.length===1&&ix.fields[0]===df.name)))return toast('Escolha uma coluna PK ou UNIQUE no destino','error');if(sf.type!==df.type)return toast('Campos da relação precisam ter tipos compatíveis','error');if(project.tables.flatMap(x=>x.foreignKeys).some(x=>x.name===name))return toast('Relacionamento duplicado','error');mutate(()=>t.foreignKeys.push({id:uid(),name,field,refTable,refField,onDelete}),'Relacionamento criado');closeModal()}}
function recordModal(index){const t=current(),editing=index!==null;const record=editing?clone(t.records[index]):{};
 openModal(editing?'Editar registro':'Adicionar registro',`<form id="recordForm"><div class="form-grid">${t.fields.map(f=>`<div class="${f.type==='BLOB SUB_TYPE TEXT'?'full':''}"><label>${escapeHtml(f.name)} ${f.primary?'🔑':''}${f.required?' *':''}</label>${f.type==='BOOLEAN'?`<select data-record-field="${escapeHtml(f.name)}"><option value="">NULL</option><option value="true" ${String(record[f.name])==='true'?'selected':''}>TRUE</option><option value="false" ${String(record[f.name])==='false'?'selected':''}>FALSE</option></select>`:f.type==='BLOB SUB_TYPE TEXT'?`<textarea data-record-field="${escapeHtml(f.name)}" rows="3">${escapeHtml(record[f.name]??'')}</textarea>`:`<input data-record-field="${escapeHtml(f.name)}" ${f.type==='DATE'?'type="date"':f.type==='TIME'?'type="time"':''} value="${escapeHtml(record[f.name]??'')}" placeholder="${f.identity?'Gerado automaticamente':f.defaultValue?'Padrão: '+f.defaultValue:'NULL'}">`}</div>`).join('')}</div></form><div class="footer-hint">Campos IDENTITY são preenchidos automaticamente quando deixados vazios. Valores NULL podem ser omitidos quando houver DEFAULT no banco.</div>`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn primary" id="saveRecord">${editing?'Salvar alterações':'Adicionar registro'}</button>`,true);
 const go=()=>{let r={};for(const f of t.fields){const input=$(`[data-record-field="${f.name}"]`,$('#recordForm'));let val=input.value.trim();if(val===''){if(f.identity&&!editing){val=String(Math.max(0,...t.records.map(r=>Number(r[f.name])||0))+1)}else if(!editing&&f.defaultValue&&/^(CURRENT_DATE|CURRENT_TIME|CURRENT_TIMESTAMP|TRUE|FALSE|-?\d+(\.\d+)?)$/i.test(f.defaultValue)){val=f.defaultValue.toUpperCase()==='TRUE'?'true':f.defaultValue.toUpperCase()==='FALSE'?'false':f.defaultValue.toUpperCase()==='CURRENT_DATE'?new Date().toISOString().slice(0,10):f.defaultValue.toUpperCase()==='CURRENT_TIMESTAMP'?new Date().toISOString().slice(0,19).replace('T',' '):f.defaultValue.toUpperCase()==='CURRENT_TIME'?new Date().toTimeString().slice(0,8):f.defaultValue}else val=null}
 if(val!==null){if(TYPES.int.includes(f.type)){if(!/^-?\d+$/.test(String(val)))return toast('Inteiro inválido: '+f.name,'error');val=Number(val)}else if(TYPES.decimal.includes(f.type)){if(!/^-?\d+(\.\d+)?$/.test(String(val)))return toast('Número inválido: '+f.name,'error')}else if(f.type==='BOOLEAN')val=val===true||val==='true'||val==='1';else if(['VARCHAR','CHAR'].includes(f.type)&&val.length>f.length)return toast(f.name+': máximo '+f.length+' caracteres','error')}
 if((f.required||f.primary)&&val===null)return toast('Campo obrigatório: '+f.name,'error');r[f.name]=val}
 const pk=t.fields.filter(f=>f.primary);if(pk.length&&t.records.some((other,i)=>i!==index&&pk.every(f=>String(other[f.name])===String(r[f.name]))))return toast('Já existe registro com esta chave primária','error');
 mutate(()=>{if(editing)t.records[index]=r;else t.records.push(r)},editing?'Registro atualizado':'Registro adicionado');closeModal();toast(editing?'Registro salvo':'Registro criado')};$('#saveRecord').onclick=go;$('#recordForm').onsubmit=e=>{e.preventDefault();go()};
}
function deleteRecord(index){const t=current();openModal('Excluir registro',`<p>Deseja excluir este registro da tabela <b>${escapeHtml(t.name)}</b>?</p>`,`<button class="btn subtle" data-close>Cancelar</button><button class="btn danger-ghost" id="confirmDeleteRecord">Excluir registro</button>`);$('#confirmDeleteRecord').onclick=()=>{mutate(()=>t.records.splice(index,1),'Registro excluído');closeModal()}}
function runQuery(){let q=($('#queryEditor')?.value||editorSql).trim();editorSql=q;try{let cleaned=q.replace(/;\s*$/,'');let m=cleaned.match(/^SELECT\s+(.*?)\s+FROM\s+"?([A-Z][A-Z0-9_]*)"?(?:\s+WHERE\s+"?([A-Z][A-Z0-9_]*)"?\s*=\s*('(?:[^']|'')*'|[-\d.]+))?(?:\s+ORDER\s+BY\s+"?([A-Z][A-Z0-9_]*)"?\s*(ASC|DESC)?)?$/is);if(!m)throw Error('Consulta local aceita SELECT colunas FROM TABELA, WHERE CAMPO = valor, ORDER BY CAMPO.');const tab=project.tables.find(x=>x.name===m[2].toUpperCase());if(!tab)throw Error('Tabela não encontrada: '+m[2]);const cols=m[1].trim();let selected;if(cols==='*')selected=tab.fields.map(x=>x.name);else if(/^COUNT\(\*\)(?:\s+AS\s+\w+)?$/i.test(cols))selected=['TOTAL'];else selected=cols.split(',').map(x=>x.trim().replace(/^"|"$/g,'').toUpperCase());if(!selected.includes('TOTAL')&&selected.some(c=>!tab.fields.some(f=>f.name===c)))throw Error('Coluna não encontrada.');let rows=[...tab.records];if(m[3]){const search=m[4].startsWith("'")?m[4].slice(1,-1).replace(/''/g,"'"):m[4];rows=rows.filter(r=>String(r[m[3].toUpperCase()]??'')===search)}if(m[5]){const col=m[5].toUpperCase(),desc=(m[6]||'ASC').toUpperCase()==='DESC';if(!tab.fields.some(x=>x.name===col))throw Error('Coluna ORDER BY não encontrada');rows.sort((a,b)=>(String(a[col]??'').localeCompare(String(b[col]??''),'pt',{numeric:true}))*(desc?-1:1))}if(selected.includes('TOTAL'))rows=[{TOTAL:rows.length}];queryResults=`<div class="table-wrap"><table class="data-table"><thead><tr>${selected.map(c=>'<th>'+escapeHtml(c)+'</th>').join('')}</tr></thead><tbody>${rows.slice(0,100).map(r=>'<tr>'+selected.map(c=>'<td>'+escapeHtml(r[c]??'NULL')+'</td>').join('')+'</tr>').join('')||`<tr><td colspan="${selected.length}" class="muted">Sem resultados</td></tr>`}</tbody></table></div><div class="small-note">${rows.length} registro(s) encontrados · consulta local</div>`;renderSql(tab);status('Consulta concluída: '+rows.length+' registro(s)');}catch(e){queryResults=`<div class="small-note error-msg">${escapeHtml(e.message)}</div>`;renderSql(current());toast(e.message,'error')}}
function csvString(rows){return rows.map(row=>row.map(v=>{let s=String(v??'');return /[",\r\n;]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(';')).join('\r\n')+'\r\n'}
function makeCSV(t){return '\ufeff'+csvString([t.fields.map(f=>f.name),...t.records.map(r=>t.fields.map(f=>r[f.name]===true?'TRUE':r[f.name]===false?'FALSE':r[f.name]))])}
function parseCSV(text){text=text.replace(/^\ufeff/,'');const delimiter=(text.split(/\r?\n/,1)[0].match(/;/g)||[]).length>=(text.split(/\r?\n/,1)[0].match(/,/g)||[]).length?';':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV com aspas abertas');row.push(cell);if(row.some(x=>x!==''))rows.push(row);return rows}
function download(name,content,mime='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportDialog(){openModal('Exportar banco de dados',`<div class="export-options"><button class="export-option" data-export="fdb"><span class="eo-icon">▣</span><span><strong>Banco de dados Firebird (.FDB) <span class="badge-inline">REAL</span></strong><small>Cria um banco Firebird 3.0 completo no servidor, com tabelas e registros.</small></span></button><button class="export-option" data-export="sql"><span class="eo-icon">⌘</span><span><strong>Script SQL (.SQL)</strong><small>Estrutura, registros, índices e relacionamentos. Abre no IBExpert.</small></span></button><button class="export-option" data-export="json"><span class="eo-icon">{ }</span><span><strong>Projeto editável (.JSON)</strong><small>Backup para continuar editando em qualquer navegador.</small></span></button><button class="export-option" data-export="csv"><span class="eo-icon">▦</span><span><strong>Registros da tabela (.CSV)</strong><small>Exporta os dados da tabela atual para planilhas.</small></span></button></div><div class="footer-hint" id="fdbHint">${fdbAvailable?'✓ Gerador .FDB disponível.':'Sem servidor Firebird: .SQL e .JSON continuam disponíveis. Para .FDB use o deploy Docker no Render.'}</div>`,`<button class="btn subtle" data-close>Fechar</button>`)}
function doExport(type){closeModal();if(type==='sql'){download(project.name+'.sql',sqlForProject(true));toast('Script SQL exportado')}else if(type==='json'){download(project.name+'.json',JSON.stringify(project,null,2),'application/json');toast('Projeto JSON exportado')}else if(type==='csv'){if(!current())return toast('Crie uma tabela','error');download(current().name+'.csv',makeCSV(current()),'text/csv;charset=utf-8');toast('CSV exportado')}else if(type==='fdb'){exportFdb()}}
async function exportFdb(){if(!fdbAvailable)return openModal('Gerador .FDB indisponível',`<p>É necessário hospedar esta aplicação como <b>Web Service (Docker)</b> no Render, para executar o Firebird Embedded 3.0 e criar um arquivo .FDB real.</p><div class="tip"><b>Você ainda pode:</b> exportar o script .SQL agora e executá-lo no IBExpert ou no FlameRobin.</div>`,`<button class="btn subtle" data-close>Entendi</button>`);
 openModal('Criando banco Firebird…','<p><span class="loading-spinner"></span> O mecanismo Firebird está montando seu banco .FDB com as tabelas e registros.</p><p class="footer-hint">Nenhuma conexão externa ou senha do seu Firebird é necessária.</p>','<button class="btn subtle" data-close>Fechar</button>');
 try{const response=await fetch('/api/export-fdb',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project})});if(!response.ok){const err=await response.json().catch(()=>({error:'Falha na criação do banco'}));throw Error(err.error||'Falha HTTP '+response.status)}const bytes=await response.blob();download(project.name+'.fdb',bytes,'application/octet-stream');closeModal();toast('Arquivo .FDB gerado: '+(bytes.size/1024/1024).toFixed(2)+' MB');status('.FDB gerado pelo Firebird com sucesso');}catch(e){closeModal();toast('Falha ao gerar .FDB: '+e.message,'error');openModal('Erro na geração do banco',`<div class="error-msg">${escapeHtml(e.message)}</div><p class="footer-hint">Verifique os campos e registros. Você pode exportar o SQL para analisar as instruções.</p>`,'<button class="btn subtle" data-close>Fechar</button>')}
}
function importProject(){ $('#importFile').accept='.json,application/json';$('#importFile').dataset.mode='json';$('#importFile').click()}
function importCSV(){ $('#importFile').accept='.csv,text/csv';$('#importFile').dataset.mode='csv';$('#importFile').click()}
function importSQL(){ $('#importFile').accept='.sql,text/plain';$('#importFile').dataset.mode='sql';$('#importFile').click()}
function importDialog(){openModal('Importar arquivo',`<div class="export-options"><button class="export-option" id="chooseJSON"><span class="eo-icon">{ }</span><span><strong>Projeto Firebird Designer (.JSON)</strong><small>Restaura todas as tabelas, campos, relacionamentos e registros.</small></span></button><button class="export-option" id="chooseCSV"><span class="eo-icon">▦</span><span><strong>Registros CSV (.CSV)</strong><small>Acrescenta registros à tabela selecionada.</small></span></button><button class="export-option" id="chooseSQL"><span class="eo-icon">⌘</span><span><strong>Script de tabelas (.SQL)</strong><small>Importação básica de declarações CREATE TABLE.</small></span></button></div><div class="footer-hint">Arquivos .FDB são binários. Para importação direta de .FDB seria necessário um módulo adicional no servidor.</div>`,`<button class="btn subtle" data-close>Fechar</button>`);$('#chooseJSON').onclick=()=>{closeModal();importProject()};$('#chooseCSV').onclick=()=>{closeModal();importCSV()};$('#chooseSQL').onclick=()=>{closeModal();importSQL()}}
function validateImported(obj){if(!obj||!Array.isArray(obj.tables)||obj.tables.length>70)throw Error('Projeto JSON inválido');const names=new Set();for(const tab of obj.tables){tab.name=cleanIdent(tab.name);if(!validIdent(tab.name)||names.has(tab.name))throw Error('Nome de tabela inválido ou duplicado');names.add(tab.name);if(!Array.isArray(tab.fields)||!tab.fields.length||tab.fields.length>120)throw Error('Campos inválidos');const fs=new Set();for(const f of tab.fields){f.name=cleanIdent(f.name);if(!validIdent(f.name)||fs.has(f.name)||!fieldTypes.includes(f.type))throw Error('Campo inválido ou repetido: '+f.name);fs.add(f.name);f.id=f.id||uid();f.length=Number(f.length)||80;f.precision=Number(f.precision)||12;f.scale=Number(f.scale)||0;}tab.id=tab.id||uid();tab.records=Array.isArray(tab.records)?tab.records.slice(0,1000):[];tab.indexes=Array.isArray(tab.indexes)?tab.indexes:[];tab.foreignKeys=Array.isArray(tab.foreignKeys)?tab.foreignKeys:[];tab.description=tab.description||'';}obj.name=cleanIdent(obj.name)||'MEU_BANCO';obj.charset=['UTF8','WIN1252','ISO8859_1','NONE'].includes(obj.charset)?obj.charset:'UTF8';obj.version=2;return obj}
function applyCSV(text){const t=current();if(!t)throw Error('Crie uma tabela antes de importar CSV');const rows=parseCSV(text);if(rows.length<2)throw Error('CSV sem dados');const headers=rows.shift().map(cleanIdent);const mapping=headers.map(n=>t.fields.find(f=>f.name===n));if(mapping.every(x=>!x))throw Error('O cabeçalho CSV não corresponde aos campos da tabela');const imported=rows.slice(0,1000).map(row=>{const obj={};mapping.forEach((f,i)=>{if(f)obj[f.name]=row[i]??null});return obj});mutate(()=>t.records.push(...imported),'CSV importado: '+imported.length+' registro(s)');toast(imported.length+' registros importados')}
function splitSqlColumns(s){let chunks=[],depth=0,quote=false,start=0;for(let i=0;i<s.length;i++){const c=s[i];if(c==="'"&&s[i-1]!=="\\")quote=!quote;if(!quote){if(c==='(')depth++;else if(c===')')depth--;else if(c===','&&depth===0){chunks.push(s.slice(start,i).trim());start=i+1}}}chunks.push(s.slice(start).trim());return chunks}
function applySQL(text){const regex=/CREATE\s+TABLE\s+"?([A-Z][A-Z0-9_]*)"?\s*\(/ig;let m,added=[],before=text.replace(/--[^\n]*/g,'');while((m=regex.exec(before))){let depth=1,pos=regex.lastIndex,begin=pos;while(pos<before.length&&depth>0){if(before[pos]==='(')depth++;else if(before[pos]===')')depth--;pos++}if(depth!==0)break;const body=before.slice(begin,pos-1);const t=newTable(cleanIdent(m[1]),[]);const keys=[];for(const chunk of splitSqlColumns(body)){let pk=chunk.match(/(?:CONSTRAINT\s+\S+\s+)?PRIMARY\s+KEY\s*\(([^)]+)\)/i);if(pk){pk[1].split(',').forEach(x=>keys.push(x.replace(/[\s"]/g,'').toUpperCase()));continue}let match=chunk.match(/^"?([A-Z][A-Z0-9_]*)"?\s+(SMALLINT|INTEGER|BIGINT|VARCHAR|CHAR|DATE|TIME|TIMESTAMP|NUMERIC|DECIMAL|FLOAT|DOUBLE PRECISION|BOOLEAN|BLOB SUB_TYPE TEXT)(?:\s*\(\s*(\d+)(?:\s*,\s*(\d+))?\s*\))?/i);if(!match)continue;const [,name,type,len,scale]=match;const f=newField(name.toUpperCase(),type.toUpperCase(),{required:/\bNOT\s+NULL\b/i.test(chunk),identity:/\bIDENTITY\b/i.test(chunk)});if(len){if(['VARCHAR','CHAR'].includes(f.type))f.length=Number(len);else f.precision=Number(len)}if(scale)f.scale=Number(scale);if(/\bPRIMARY\s+KEY\b/i.test(chunk))f.primary=true;t.fields.push(f)}t.fields.forEach(f=>{if(keys.includes(f.name)){f.primary=true;f.required=true}});if(t.fields.length&&validIdent(t.name)&&!project.tables.some(x=>x.name===t.name)&&!added.some(x=>x.name===t.name))added.push(t);regex.lastIndex=pos}
 if(!added.length)throw Error('Nenhum CREATE TABLE simples e válido encontrado.');mutate(()=>{project.tables.push(...added);currentId=added[0].id;activeView='structure'},added.length+' tabela(s) importada(s)');toast(added.length+' tabelas importadas; revise índices, FKs e dados (importação SQL parcial)')}
async function handleFile(e){const file=e.target.files[0];const mode=e.target.dataset.mode;e.target.value='';if(!file)return;if(file.size>2_000_000)return toast('Arquivo muito grande (limite 2 MB)','error');try{const txt=await file.text();if(mode==='json'){const obj=validateImported(JSON.parse(txt));mutate(()=>{project=obj;currentId=obj.tables[0]?.id||null;selectedFieldId=null;activeView='structure'},'Projeto importado');toast('Projeto restaurado: '+obj.tables.length+' tabela(s)')}else if(mode==='csv')applyCSV(txt);else if(mode==='sql')applySQL(txt)}catch(err){toast('Importação falhou: '+err.message,'error')}}
function help(){openModal('Como utilizar o Firebird Designer',`<div class="options-grid"><div class="help-card"><strong>1. Criar tabelas</strong><p>Use + Nova tabela, edite nome e tipos dos campos. Você pode adicionar PK, campos obrigatórios e IDENTITY.</p></div><div class="help-card"><strong>2. Adicionar registros</strong><p>Na aba Dados, crie, altere, exclua e importe registros CSV.</p></div><div class="help-card"><strong>3. Relacionamentos e índices</strong><p>Configure chaves estrangeiras e índices para a estrutura do Firebird.</p></div><div class="help-card"><strong>4. Baixar .FDB real</strong><p>No Render com Docker, Exportar → Firebird (.FDB) cria um arquivo real compatível com Firebird 3.0, sem servidor externo.</p></div></div><hr class="secondary-line"><div class="tip"><b>Importante:</b> o site salva o projeto no armazenamento local deste navegador. Baixe também um JSON como cópia de segurança. Não é um painel conectado ao seu Firebird instalado no Windows.</div>`,`<button class="btn primary" data-close>Começar</button>`,true)}
function renameProject(){askName('Renomear banco','Nome do projeto / banco',project.name,name=>{mutate(()=>project.name=name,'Projeto renomeado')})}
function handleInspect(target){const t=current(),key=target.dataset.inspect;if(key==='project-name'){const name=cleanIdent(target.value);if(!validIdent(name))return toast('Nome inválido','error');mutate(()=>project.name=name);return}if(key==='project-charset')return mutate(()=>project.charset=target.value,'Charset alterado');if(!t)return;if(key==='table-name'){const name=cleanIdent(target.value);if(!validIdent(name)||!validateTableName(name,t.id))return;return mutate(()=>{const old=t.name;t.name=name;project.tables.forEach(tab=>tab.foreignKeys.forEach(fk=>{if(fk.refTable===old)fk.refTable=name}))})}if(key==='table-desc')return mutate(()=>t.description=target.value,'Descrição atualizada');if(!selectedFieldId)return;const f=t.fields.find(f=>f.id===selectedFieldId);if(!f)return;if(key==='field-name')return updateField(f.id,'name',target);if(key==='field-type')return updateField(f.id,'type',target);if(key==='defaultValue')return updateField(f.id,'defaultValue',target);if(key==='precision'){const v=Number(target.value);if(v<1||v>18)return toast('Precisão entre 1 e 18','error');return mutate(()=>f.precision=v)}if(key==='scale'){const v=Number(target.value);if(v<0||v>f.precision)return toast('Escala inválida','error');return mutate(()=>f.scale=v)}}
function bindEvents(){
 document.addEventListener('click',e=>{
  const b=e.target.closest('button,[data-table],[data-diagram-table]');if(!b)return;
  if(b.hasAttribute('data-close'))return closeModal();
  if(b.dataset.table){currentId=b.dataset.table;selectedFieldId=null;dataFilter='';render();return}
  if(b.dataset.diagramTable){currentId=b.dataset.diagramTable;activeView='structure';selectedFieldId=null;render();return}
  if(b.dataset.view){activeView=b.dataset.view;queryResults=null;render();return}
  if(b.dataset.export){doExport(b.dataset.export);return}
  if(b.dataset.act==='selectField'){selectedFieldId=b.closest('[data-field]').dataset.field;renderInspector(current());return}
  if(b.dataset.act==='deleteField'){deleteField(b.closest('[data-field]').dataset.field);return}
  if(b.dataset.removeIndex){const t=current();mutate(()=>t.indexes=t.indexes.filter(x=>x.id!==b.dataset.removeIndex),'Índice excluído');return}
  if(b.dataset.removeRel){const t=current();mutate(()=>t.foreignKeys=t.foreignKeys.filter(x=>x.id!==b.dataset.removeRel),'Relacionamento excluído');return}
  if(b.dataset.editRecord!==undefined)return recordModal(Number(b.dataset.editRecord));
  if(b.dataset.deleteRecord!==undefined)return deleteRecord(Number(b.dataset.deleteRecord));
  const handlers={renameProject,btnNewDatabase:newDatabase,createTableMini:createTable,addTableAside:createTable,newTableTab:createTable,railNew:createTable,emptyCreate:createTable,duplicateTable,editTableName:renameTable,deleteTable,addField,addIndex,addRelation,newRecord:()=>recordModal(null),btnUndo:undo,btnRedo:redo,btnExport:exportDialog,inspectExport:exportDialog,btnImport:importDialog,downloadSQL:()=>doExport('sql'),downloadCSV:()=>doExport('csv'),copySQL:()=>{navigator.clipboard?.writeText(sqlForProject(true)).then(()=>toast('SQL copiado')).catch(()=>toast('Use o botão Baixar SQL','error'))},runQuery,railSQL:()=>{activeView='sql';render()},railHelp:help,themeToggle:()=>{document.body.classList.toggle('light');localStorage.setItem('firebird-theme',document.body.classList.contains('light')?'light':'dark')},diagramPrint:()=>window.print(),clearFieldSelection:()=>{selectedFieldId=null;renderInspector(current())},importCSV,};
  if(handlers[b.id])handlers[b.id]();
 });
 document.addEventListener('change',e=>{const el=e.target;if(el.classList.contains('field-edit')){updateField(el.closest('[data-field]').dataset.field,el.dataset.key,el)}else if(el.dataset.inspect)handleInspect(el)});
 document.addEventListener('input',e=>{if(e.target.id==='queryEditor')editorSql=e.target.value;else if(e.target.id==='dataSearch'){dataFilter=e.target.value;const t=current();const q=dataFilter.toLowerCase();const ids=t.records.map((r,i)=>({r,i})).filter(({r})=>!q||Object.values(r).some(v=>String(v??'').toLowerCase().includes(q)));$('#filterCount').textContent=ids.length+' de '+t.records.length+' registros';$('#recordRows').innerHTML=ids.slice(0,100).map(({r,i})=>`<tr><td class="row-num">${i+1}</td>${t.fields.map(f=>`<td class="grid-value">${escapeHtml(r[f.name]??'NULL')}</td>`).join('')}<td><button class="text-button" data-edit-record="${i}">Editar</button><button class="text-button danger" data-delete-record="${i}">Excluir</button></td></tr>`).join('')||`<tr><td colspan="${t.fields.length+2}" class="muted">Nenhum registro encontrado</td></tr>`}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modalRoot').children.length)closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();toast('Projeto salvo no navegador')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input,textarea,[contenteditable]')){e.preventDefault();undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'&&!e.target.matches('input,textarea,[contenteditable]')){e.preventDefault();redo()}});
 $('#importFile').addEventListener('change',handleFile);
}
async function probeBackend(){try{const ctl=new AbortController();const h=setTimeout(()=>ctl.abort(),3200);const r=await fetch('/api/health',{signal:ctl.signal});clearTimeout(h);const j=await r.json();fdbAvailable=!!j.fdb;$('#backendStatus').textContent=fdbAvailable?'Gerador FDB online':'Modo editor local';}catch(e){fdbAvailable=false;$('#backendStatus').textContent='Modo editor local'} }
if(localStorage.getItem('firebird-theme')==='light')document.body.classList.add('light');
bindEvents();render();save();probeBackend();
